<?php
require __DIR__.'/../includes/bootstrap.php';require_admin($conn);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post_string('action');$id=(int)($_POST['id']??0);
try{if($action==='delete'){$st=$conn->prepare("UPDATE books SET status='inactive' WHERE id=?");$st->bind_param('i',$id);$st->execute();flash('success','Book archived.');redirect('admin/books.php');}
$title=post_string('title',200);$author=post_string('author',150);$desc=post_string('description',4000);$cat=(int)($_POST['category_id']??0);$price=(float)($_POST['price']??0);$stock=max(0,(int)($_POST['stock']??0));$cover=valid_image_upload($_FILES['cover']??[]);
if($title===''||$author===''||$cat<1||$price<0)throw new RuntimeException('Complete all required fields.');
if($id){if($cover){$st=$conn->prepare("UPDATE books SET category_id=?,title=?,author=?,description=?,price=?,stock=?,cover_image=? WHERE id=?");$st->bind_param('isssdisi',$cat,$title,$author,$desc,$price,$stock,$cover,$id);}else{$st=$conn->prepare("UPDATE books SET category_id=?,title=?,author=?,description=?,price=?,stock=? WHERE id=?");$st->bind_param('isssdii',$cat,$title,$author,$desc,$price,$stock,$id);}$st->execute();}
else{$st=$conn->prepare("INSERT INTO books(category_id,title,author,description,price,stock,cover_image) VALUES(?,?,?,?,?,?,?)");$st->bind_param('isssdis',$cat,$title,$author,$desc,$price,$stock,$cover);$st->execute();}
flash('success','Book saved.');redirect('admin/books.php');
}catch(Throwable $e){$error=$e->getMessage();}}
$cats=$conn->query("SELECT id,name FROM categories ORDER BY name")->fetch_all(MYSQLI_ASSOC);$books=$conn->query("SELECT b.id,b.title,b.author,b.price,b.stock,c.name category FROM books b JOIN categories c ON c.id=b.category_id WHERE b.status='active' ORDER BY b.id DESC")->fetch_all(MYSQLI_ASSOC);
$pageTitle='Manage books';require __DIR__.'/../includes/header.php';?>
<section class="page-hero"><div class="container"><p class="eyebrow">ADMINISTRATION</p><h1>Manage <em>books.</em></h1></div></section><section class="container section"><form method="post" enctype="multipart/form-data" class="admin-form"><?=csrf_field()?><input type="hidden" name="action" value="save"><h2>Add a book</h2><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="form-grid"><label>Title<input name="title" required></label><label>Author<input name="author" required></label><label>Category<select name="category_id" required><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Price<input type="number" step=".01" min="0" name="price" required></label><label>Stock<input type="number" min="0" name="stock" value="1" required></label><label>Cover image<input type="file" name="cover" accept="image/jpeg,image/png,image/webp"></label></div><label>Description<textarea name="description" rows="3"></textarea></label><button class="btn btn-dark">Save book ↗</button></form><h2 class="mt-40">Current books</h2><div class="table-wrap"><table><thead><tr><th>Title</th><th>Author</th><th>Category</th><th>Price</th><th>Stock</th><th></th></tr></thead><tbody><?php foreach($books as $b):?><tr><td><?=e($b['title'])?></td><td><?=e($b['author'])?></td><td><?=e($b['category'])?></td><td><?=money($b['price'])?></td><td><?=$b['stock']?></td><td><a class="text-link" href="book-edit.php?id=<?=$b['id']?>">Edit</a> · <form method="post" onsubmit="return confirm('Archive this book?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="text-link danger-text">Archive</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>
